import { createTag } from '../../../utils/utils.js';
import { logWarning } from '../../../utils/lana-log.js';

/*
 * Generated by site-to-da (shapes seen: items; used 1x). Review before merging.
 * Authoring:
 *   - several rows, each [media?, text]  -> one item per row (grid of up to 4)
 *   - a single row with N cells          -> one item per cell
 *   - several rows with 3+ text cells    -> table-like rows
 */
const MAX_COLS = 4;
const cellsOf = (row) => [...row.querySelectorAll(':scope > div')];

function decorateCell(cell) {
  const hasText = cell.textContent.trim().length > 0;
  cell.classList.add(cell.querySelector('img') && !hasText ? 'event-session-media' : 'event-session-text');
  return cell;
}

export default async function init(el) {
  const rows = [...el.querySelectorAll(':scope > div')];
  if (!rows.length) {
    logWarning('event-session', 'no content rows');
    el.remove();
    return;
  }

  const tableLike = rows.length > 1 && rows.every((row) => cellsOf(row).length >= 3);
  const list = createTag('ul', { class: 'event-session-list' });
  if (tableLike) list.classList.add('is-table');

  if (rows.length === 1) {
    cellsOf(rows[0]).forEach((cell) => {
      list.append(createTag('li', { class: 'event-session-item' }, decorateCell(cell)));
    });
  } else {
    rows.forEach((row) => {
      const cells = cellsOf(row);
      const item = createTag('li', { class: 'event-session-item' }, cells.map(decorateCell));
      if (tableLike) item.style.setProperty('--event-session-cells', String(cells.length));
      list.append(item);
    });
  }

  el.replaceChildren(list);
  const cols = tableLike ? 1 : Math.min(list.children.length, MAX_COLS);
  // Auto column count; a theme can override it with --event-session-cols in CSS.
  el.style.setProperty('--event-session-auto-cols', String(cols));
}
